        max(case when SOURCE_RUN = 'opus_health_delta3' then ENDORSEMENT_RAISED_DUE_TO_CODE end) as ENDORSEMENT_RAISED_DUE_TO_CODE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then ENDORSEMENT_WORDING_TEXT end) as ENDORSEMENT_WORDING_TEXT,
