        max(case when SOURCE_RUN = 'opus_health_delta3' then MAIN_AGENT_SERVICE_CHARGE_ON_ENDORSEMENT end) as MAIN_AGENT_SERVICE_CHARGE_ON_ENDORSEMENT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SUB_AGENT_SERVICE_CHARGE_ON_ENDORSEMENT end) as SUB_AGENT_SERVICE_CHARGE_ON_ENDORSEMENT,
